// tests/dist/exports.test.ts
// The runtime export snapshot, taken through the package exports map: a child node process whose cwd
// is packages/modern-cmdk imports 'modern-cmdk', 'modern-cmdk/react' and 'modern-cmdk/react/dialog' by
// name (package self-reference, no alias), so dist and the exports map are what is exercised.
// Needs: pnpm build. The expected arrays are literals: a new or removed export fails here and is
// reviewed in the diff, never regenerated by the test.

import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

const root = resolve(import.meta.dirname, '../..');
const packageDir = resolve(root, 'packages/modern-cmdk');
const TIMEOUT_MS = 30_000;

/** Sorted own keys of the module namespace that `specifier` resolves to from inside the package. */
function runtimeKeys(specifier: string): string[] {
  const script = `const m = await import(${JSON.stringify(specifier)}); process.stdout.write(JSON.stringify(Object.keys(m).sort()));`;
  const out = execFileSync(process.execPath, ['--input-type=module', '-e', script], {
    cwd: packageDir,
    encoding: 'utf8',
    timeout: TIMEOUT_MS,
  });
  return JSON.parse(out) as string[];
}

/** Every string target in an exports map (nested conditions included), without the leading './'. */
function exportTargets(value: unknown): string[] {
  if (typeof value === 'string') return [value.replace(/^\.\//, '')];
  if (value !== null && typeof value === 'object')
    return Object.values(value).flatMap(exportTargets);
  return [];
}

describe('package exports', () => {
  it('runtime exports of modern-cmdk', () => {
    expect(runtimeKeys('modern-cmdk')).toEqual([
      'CommandRegistry',
      'DEFAULT_FRECENCY_DECAY',
      'DEFAULT_MACHINE_OPTIONS',
      'FrecencyEngine',
      'IdbFrecencyStorage',
      'KeyboardShortcutRegistry',
      'MemoryFrecencyStorage',
      'TypedEmitter',
      'batchScoreItems',
      'computeFrecencyBonus',
      'createCommandMachine',
      'createInitialState',
      'createScheduler',
      'createSearchEngine',
      'createTelemetryMiddleware',
      'detectConflicts',
      'findMatchingShortcut',
      'formatShortcut',
      'groupId',
      'itemId',
      'matchesShortcut',
      'parseShortcut',
      'scoreItem',
      'scoreItemAsync',
    ]);
  });

  it('runtime exports of modern-cmdk/react', () => {
    expect(runtimeKeys('modern-cmdk/react')).toEqual([
      'Command',
      'CommandActivity',
      'CommandAsyncItems',
      'CommandBadge',
      'CommandDialog',
      'CommandEmpty',
      'CommandErrorBoundary',
      'CommandGroup',
      'CommandHighlight',
      'CommandInput',
      'CommandItem',
      'CommandList',
      'CommandLoading',
      'CommandPage',
      'CommandSeparator',
      'CommandShortcut',
      'CommandStableContext',
      'CommandStateContext',
      'createKeydownHandler',
      'useCommand',
      'useCommandDevtools',
      'useCommandState',
      'useRegisterGroup',
      'useRegisterItem',
      'useVirtualizer',
    ]);
  });

  it('runtime exports of modern-cmdk/react/dialog', () => {
    expect(runtimeKeys('modern-cmdk/react/dialog')).toEqual(['CommandDialog']);
  });

  it('every exports target is in the tarball file list', () => {
    const pkg = JSON.parse(readFileSync(resolve(packageDir, 'package.json'), 'utf8')) as {
      exports: unknown;
      main: string;
      types: string;
      bin: Record<string, string>;
    };
    const listed = new Set(
      JSON.parse(
        readFileSync(resolve(root, 'tests/package/modern-cmdk.files.json'), 'utf8'),
      ) as string[],
    );
    const targets = [
      ...exportTargets(pkg.exports),
      ...exportTargets(pkg.main),
      ...exportTargets(pkg.types),
      ...exportTargets(pkg.bin),
    ];
    expect(targets.length).toBeGreaterThan(0);
    expect(targets.filter((target) => !listed.has(target))).toEqual([]);
  });
});
